 6	  try {
 7	    res.end(await readFile(new URL('.' + (req.url === '/' ? '/index.html' : req.url), import.meta.url)));
 8	  } catch {
 9	    res.writeHead(404).end('not found');
10	  }
11	});
12	
13	console.log('warming up the asset cache...');
